    def json_value(value):
        if hasattr(value, 'isoformat'):
            return value.isoformat()
        if value is not None and value.__class__.__name__ == 'Decimal':
            return str(value)
        return value

    events = []
    for commission in Commission.objects.select_related('billing', 'customer').order_by('earned_at', 'id'):
        billing = commission.billing
        items = []
        for item in BillingItem.objects.filter(billing_id=billing.id).order_by('id').values(
            'instance_no', 'description', 'service_type', 'product_name',
            'period_start', 'period_end', 'amount', 'currency',
        ):
            items.append({key: json_value(value) for key, value in item.items()})
        payments = []
        for payment in PaymentTransaction.objects.filter(
            billing_id=billing.id,
            status='succeeded',
        ).order_by('paid_at', 'id').values(
            'transaction_no', 'provider', 'provider_payment_id', 'amount', 'currency', 'paid_at',
        ):
            payments.append({key: json_value(value) for key, value in payment.items()})
        Commission.objects.filter(pk=commission.pk).update(
            customer_no=commission.customer.customer_no,
            customer_name=commission.customer.name,
            gross_amount=billing.gross_amount,
            promotion_discount_amount=billing.promotion_discount_amount,
            billing_amount=billing.amount,
            billing_period=billing.bill_month,
            billing_paid_at=billing.paid_at,
            service_items_snapshot=items,
            payment_summary_snapshot={
                'payment_method': billing.payment_method,
                'paid_amount': str(billing.paid_amount),
                'paid_at': billing.paid_at.isoformat() if billing.paid_at else None,
                'transactions': payments,
            },
        )
        common = {
            'channel_id': commission.channel_id,
            'currency': commission.currency,
            'source_type': 'channel_commission',
            'source_id': str(commission.pk),
        }
        events.append((
            commission.earned_at,
            commission.pk * 10,
            {
                **common,
                'entry_type': 'accrual',
                'delta': commission.commission_amount,
                'snapshot': {
                    'commission_id': commission.pk,
                    'billing_id': commission.billing_id,
                    'bill_no': commission.bill_no,
                    'customer_id': commission.customer_id,
                    'amount': str(commission.commission_amount),
                },
                'idempotency_key': f'commission:{commission.pk}:accrual',
            },
        ))
        if commission.status == 'void':
            events.append((
                commission.updated_at,
                commission.pk * 10 + 1,
                {
                    **common,
                    'entry_type': 'void',
                    'delta': -commission.commission_amount,
                    'snapshot': {
                        'commission_id': commission.pk,
                        'bill_no': commission.bill_no,
                        'reason': commission.void_reason,
                        'amount': str(commission.commission_amount),
                    },
                    'idempotency_key': f'commission:{commission.pk}:void',
                },
            ))

    for settlement in Settlement.objects.select_related('channel').order_by('created_at', 'id'):
        Settlement.objects.filter(pk=settlement.pk).update(
            channel_no=settlement.channel.customer_no,
            channel_name=settlement.channel.name,
        )
        if settlement.status == 'paid' and not settlement.payment_method:
            Settlement.objects.filter(pk=settlement.pk).update(payment_method='other')
        common = {
            'channel_id': settlement.channel_id,
            'currency': settlement.currency,
            'source_type': 'channel_settlement',
            'source_id': str(settlement.pk),
        }
        events.append((
            settlement.created_at,
            settlement.pk * 10 + 2,
            {
                **common,
                'entry_type': 'settlement_created',
                'delta': 0,
                'snapshot': {
                    'settlement_no': settlement.settlement_no,
                    'commission_ids': list(
                        commission.id for commission in settlement.commissions.all()
                    ),
                    'total_amount': str(settlement.total_amount),
                    'payout_profile': {},
                },
                'idempotency_key': f'settlement:{settlement.pk}:created',
            },
        ))
        if settlement.status == 'cancelled':
            events.append((
                settlement.updated_at,
                settlement.pk * 10 + 3,
                {
                    **common,
                    'entry_type': 'settlement_cancelled',
                    'delta': 0,
                    'snapshot': {
                        'settlement_no': settlement.settlement_no,
                        'total_amount': str(settlement.total_amount),
                    },
                    'idempotency_key': f'settlement:{settlement.pk}:cancelled',
                },
            ))
        elif settlement.status == 'paid':
            events.append((
                settlement.paid_at or settlement.updated_at,
                settlement.pk * 10 + 4,
                {
                    **common,
                    'entry_type': 'payout',
                    'delta': -settlement.total_amount,
                    'snapshot': {
                        'settlement_no': settlement.settlement_no,
                        'payment_method': settlement.payment_method or 'other',
                        'payment_reference': settlement.payment_reference,
                        'total_amount': str(settlement.total_amount),
                    },
                    'idempotency_key': f'settlement:{settlement.pk}:payout',
                },
            ))

    balances = {}
    for occurred_at, _, event in sorted(events, key=lambda row: (row[0], row[1])):
        key = (event.pop('channel_id'), str(event.pop('currency') or 'CNY').upper())
        account, _ = Account.objects.get_or_create(
            channel_id=key[0],
            currency=key[1],
            defaults={'balance': 0},
        )
        balance = balances.get(key, account.balance) + event['delta']
        ledger = Ledger.objects.create(
            account_id=account.pk,
            balance_after=balance,
            **event,
        )
        Ledger.objects.filter(pk=ledger.pk).update(created_at=occurred_at)
        balances[key] = balance
    for (channel_id, currency), balance in balances.items():
        Account.objects.filter(channel_id=channel_id, currency=currency).update(balance=balance)


